const config = $('Configuration').first().json;
const workspace = $('Get Workspace Overview').first().json;
const draftResponse = $('Get Full Page Draft').first().json;
const publicationResponse = $('Get Publication Status').first().json;
const draft = draftResponse.data || {};
const publication = publicationResponse.body?.data || publicationResponse.data || {};
const headers = publicationResponse.headers || {};
const draftRevision = Number(publication.draftRevision ?? draftResponse.revision ?? workspace.revision);
const publishedRevision = Number(publication.publishedRevision ?? 0);
const publicUrl = String(publication.publicUrl || workspace.publicUrl || '').trim();
const approvedEtag = String(headers.etag || headers.ETag || headers['x-orbitpage-revision'] || (Number.isSafeInteger(draftRevision) ? draftRevision : '')).trim();
const publishEnabled = String(config.ENABLE_PUBLISH || '').trim().toUpperCase() === 'YES';
const sendSuccessEmail = String(config.SEND_SUCCESS_EMAIL || '').trim().toUpperCase() === 'YES';
const workspaceKey = String(workspace.tenant?.tenantId || workspace.workspace?.tenantId || workspace.page?.pageId || workspace.pageId || 'orbitpage-workspace');

const safeText = (value, max = 160) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const projectLink = (item = {}) => ({ id: safeText(item.id, 128), type: safeText(item.type, 40), title: safeText(item.title), url: safeText(item.url, 500), isActive: item.isActive !== false, status: safeText(item.status, 40), position: Number(item.position ?? 0) });
const projectPage = (item = {}) => ({ id: safeText(item.id, 128), slug: safeText(item.slug, 128), title: safeText(item.title), active: item.isActive !== false, blocks: Array.isArray(item.blocks) ? item.blocks.map(projectLink) : [] });
const snapshot = {
  profile: { name: safeText(draft.profile?.name || draft.profile?.displayName || draft.profile?.title), bio: safeText(draft.profile?.bio, 500), browserTitle: safeText(draft.profile?.browserTitle || draft.profile?.seoTitle), seoDescription: safeText(draft.profile?.seoDescription, 500) },
  links: Array.isArray(draft.links) ? draft.links.map(projectLink) : [],
  subpages: Array.isArray(draft.subpages) ? draft.subpages.map(projectPage) : [],
  theme: { preset: safeText(draft.theme?.preset || draft.theme?.name), font: safeText(draft.theme?.fontFamily || draft.theme?.font), background: safeText(draft.theme?.backgroundColor || draft.theme?.background) },
  menu: { enabled: Boolean(draft.menu?.enabled), homepage: safeText(draft.menu?.routing?.homepage), sectionCount: Array.isArray(draft.menu?.sections) ? draft.menu.sections.length : 0 },
  privacy: { enabled: Boolean(draft.consentConfig?.enabled), mode: safeText(draft.consentConfig?.mode) },
  textFiles: Array.isArray(draft.textFiles) ? draft.textFiles.map((item) => safeText(item.path || item.key, 128)).filter(Boolean) : []
};

const state = $getWorkflowStaticData('global');
const sameWorkspace = state.releaseGuardian?.workspaceKey === workspaceKey;
const previous = sameWorkspace ? state.releaseGuardian.snapshot : null;
const previousVerifiedRevision = sameWorkspace ? Number(state.releaseGuardian.revision ?? 0) : 0;
const changedSections = [];
for (const key of Object.keys(snapshot)) if (!previous || JSON.stringify(previous[key]) !== JSON.stringify(snapshot[key])) changedSections.push(key);
const byId = (items) => new Map((items || []).filter((item) => item.id).map((item) => [item.id, item]));
const oldLinks = byId(previous?.links);
const newLinks = byId(snapshot.links);
const addedLinks = [...newLinks.keys()].filter((id) => !oldLinks.has(id));
const removedLinks = [...oldLinks.keys()].filter((id) => !newLinks.has(id));
const changedLinks = [...newLinks.keys()].filter((id) => oldLinks.has(id) && JSON.stringify(oldLinks.get(id)) !== JSON.stringify(newLinks.get(id)));

const blockers = [];
const warnings = [];
if (!Number.isSafeInteger(draftRevision) || draftRevision < 0) blockers.push('OrbitPage did not return a valid draft revision.');
if (!Number.isSafeInteger(publishedRevision) || publishedRevision < 0) blockers.push('OrbitPage did not return a valid published revision.');
if (!approvedEtag) blockers.push('The publication response did not contain an ETag or revision.');
if (!/^https:\/\//i.test(publicUrl)) blockers.push('The public URL is missing or is not HTTPS.');

const findings = [];
const walk = (value, path = 'draft', depth = 0) => {
  if (depth > 8 || findings.length >= 25 || value == null) return;
  if (typeof value === 'string') {
    if (/REPLACE_WITH|\bTODO\b|\bTBD\b/i.test(value)) findings.push(`${path}: placeholder text`);
    if (/(?:url|href)$/i.test(path) && /^(?:javascript:|file:|data:text\/html)/i.test(value.trim())) findings.push(`${path}: unsafe URL protocol`);
    return;
  }
  if (Array.isArray(value)) return value.forEach((entry, index) => walk(entry, `${path}[${index}]`, depth + 1));
  if (typeof value === 'object') for (const [key, entry] of Object.entries(value)) walk(entry, `${path}.${key}`, depth + 1);
};
walk(draft);
if (findings.length) blockers.push(...findings);
if (!snapshot.links.length && !snapshot.subpages.length) warnings.push('The draft contains no main blocks or subpages.');
if (!previous) warnings.push('No prior Guardian snapshot exists yet; this first review is a baseline rather than a field-by-field comparison.');
if (publication.publicationError) warnings.push(`OrbitPage reports a previous publication error: ${safeText(publication.publicationError, 240)}`);

const needsPublication = draftRevision !== publishedRevision;
const publishedReleaseChanged = !needsPublication && publishedRevision > 0 && publishedRevision !== previousVerifiedRevision;
const verifyPublishedRelease = publishedReleaseChanged && /^https:\/\//i.test(publicUrl);
const rollbackRevision = needsPublication ? publishedRevision : previousVerifiedRevision;
const readyForApproval = publishEnabled && needsPublication && blockers.length === 0;
const notifyBlocked = publishEnabled && needsPublication && blockers.length > 0;
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const diffLines = previous
  ? [
      `Changed sections: ${changedSections.join(', ') || 'none'}`,
      `Blocks added: ${addedLinks.join(', ') || 'none'}`,
      `Blocks changed: ${changedLinks.join(', ') || 'none'}`,
      `Blocks removed: ${removedLinks.join(', ') || 'none'}`
    ]
  : [`Baseline: ${snapshot.links.length} blocks and ${snapshot.subpages.length} subpages`];
const summary = [
  `Draft revision: ${draftRevision}`,
  `Published revision: ${publishedRevision}`,
  `Public URL: ${publicUrl}`,
  ...diffLines,
  ...(warnings.length ? [`Warnings: ${warnings.join(' | ')}`] : []),
  ...(blockers.length ? [`Findings: ${blockers.join(' | ')}`] : [])
].join('\n');
const list = (items, empty) => `<ul>${(items.length ? items : [empty]).map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
const approvalHtml = `<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;color:#202124"><h2>OrbitPage Release Guardian</h2><p>A private draft is ready for review.</p><table style="border-collapse:collapse;width:100%"><tr><td style="padding:6px;font-weight:bold">Draft revision</td><td style="padding:6px">${draftRevision}</td></tr><tr><td style="padding:6px;font-weight:bold">Published revision</td><td style="padding:6px">${publishedRevision}</td></tr><tr><td style="padding:6px;font-weight:bold">Public URL</td><td style="padding:6px">${escapeHtml(publicUrl)}</td></tr></table><h3>Changes</h3>${list(diffLines, 'No differences detected.')}<h3>Warnings</h3>${list(warnings, 'None')}<p><strong>Approval publishes exactly revision ${draftRevision}.</strong> If the draft changes before the click is processed, OrbitPage rejects the stale ETag.</p><p><a href="APPROVAL_URL" style="display:inline-block;padding:12px 18px;background:#2563eb;color:#fff;text-decoration:none;border-radius:8px">Approve and publish</a></p><p style="font-size:12px;color:#666">Do not forward this approval link. Ignore it to reject or let it expire.</p></div>`;

return [{ json: { workspaceKey, draftRevision, previousPublishedRevision: publishedRevision, previousVerifiedRevision, rollbackRevision, publicUrl, approvedEtag, publishEnabled, sendSuccessEmail, needsPublication, publishedReleaseChanged, verifyPublishedRelease, readyForApproval, notifyBlocked, blockers, warnings, changedSections, addedLinks, changedLinks, removedLinks, summary, approvalHtml, currentSnapshot: snapshot } }];

const response = $input.first().json;
const status = Number(response.statusCode ?? response.status ?? 0);
const body = String(response.body ?? response.data ?? '');
const analysis = $('Analyze Draft').first().json;
const hasSuccessStatus = status ? status >= 200 && status < 400 : body.length > 0;
const liveCheckPassed = hasSuccessStatus && body.length > 80 && !/under construction/i.test(body);
return [{ json: { liveCheckPassed, statusCode: status || null, bodyBytes: body.length, checkedAt: new Date().toISOString(), publicUrl: analysis.publicUrl, rollbackRevision: analysis.rollbackRevision, canRollback: !liveCheckPassed && Number(analysis.rollbackRevision) > 0 } }];

const analysis = $('Analyze Draft').first().json;
const check = $('Verify Published Page').first().json;
const state = $getWorkflowStaticData('global');
state.releaseGuardian = { workspaceKey: analysis.workspaceKey, revision: analysis.draftRevision, snapshot: analysis.currentSnapshot, updatedAt: new Date().toISOString() };
return [{ json: { status: 'published_and_verified', draftRevision: analysis.draftRevision, previousPublishedRevision: analysis.previousPublishedRevision, publicUrl: analysis.publicUrl, checkedAt: check.checkedAt, statusCode: check.statusCode, changedSections: analysis.changedSections, warnings: analysis.warnings } }];

const response = $input.first().json;
const body = response.body || response;
const headers = response.headers || {};
const targetRevision = Number($('Analyze Draft').first().json.rollbackRevision);
const versions = Array.isArray(body.versions) ? body.versions : [];
if (!versions.some((version) => Number(version.revision) === targetRevision)) throw new Error(`Previous verified revision ${targetRevision} is not available for rollback.`);
const rollbackEtag = String(headers.etag || headers.ETag || headers['x-orbitpage-revision'] || body.currentRevision || '').trim();
if (!rollbackEtag) throw new Error('OrbitPage did not return the current revision required for a safe rollback.');
const publicUrl = $('Analyze Draft').first().json.publicUrl;
const html = `<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;color:#202124"><h2>OrbitPage live check failed</h2><p>The published page did not pass the HTTP smoke test after three attempts.</p><ul><li>URL: ${publicUrl}</li><li>Failed release: ${$('Analyze Draft').first().json.draftRevision}</li><li>Last verified rollback target: ${targetRevision}</li></ul><p>Confirming restores and immediately republishes the last revision verified by this workflow. If the workspace changes before approval, the stored ETag makes the restore fail safely.</p><p><a href="ROLLBACK_URL" style="display:inline-block;padding:12px 18px;background:#b42318;color:#fff;text-decoration:none;border-radius:8px">Approve rollback</a></p><p style="font-size:12px;color:#666">Ignore this link to keep the current version and investigate manually.</p></div>`;
return [{ json: { targetRevision, rollbackEtag, html, publicUrl } }];

const response = $input.first().json;
const status = Number(response.statusCode ?? response.status ?? 0);
const body = String(response.body ?? response.data ?? '');
const restoredPagePassed = (status ? status >= 200 && status < 400 : body.length > 0) && body.length > 80 && !/under construction/i.test(body);
if (!restoredPagePassed) throw new Error(`Rollback completed but the restored public page still failed verification (HTTP ${status || 'unknown'}).`);
return [{ json: { status: 'rolled_back_and_verified', restoredRevision: $('Prepare Rollback Approval').first().json.targetRevision, replacedRevision: $('Analyze Draft').first().json.draftRevision, publicUrl: $('Analyze Draft').first().json.publicUrl, statusCode: status || null, checkedAt: new Date().toISOString() } }];

const analysis = $('Analyze Draft').first().json;
let status = 'private_draft_dry_run';
if (!analysis.needsPublication && !analysis.publishedReleaseChanged) status = 'duplicate_published_revision';
else if (!analysis.needsPublication) status = 'published_check_blocked';
else if (analysis.blockers.length) status = 'private_draft_blocked';
return [{ json: { status, publishEnabled: analysis.publishEnabled, draftRevision: analysis.draftRevision, publishedRevision: analysis.previousPublishedRevision, publicUrl: analysis.publicUrl, summary: analysis.summary, blockers: analysis.blockers, warnings: analysis.warnings, notifyBlocked: analysis.notifyBlocked, nextStep: status === 'private_draft_dry_run' ? 'Set ENABLE_PUBLISH to YES only if this private API draft should enter email approval.' : status === 'private_draft_blocked' ? 'Fix the findings in OrbitPage and wait for the next saved revision.' : status === 'published_check_blocked' ? 'Fix the public URL or invalid revision data before live verification can run.' : 'This published revision was already verified; no action is required.' } }];

